(()=>{const body=document.body,context=document.getElementById('context'),title=context.querySelector('h2'),eyebrow=context.querySelector('.context-eyebrow'),copy=context.querySelector('.context-copy'),action=context.querySelector('.context-action'),toggle=document.getElementById('motionToggle');const data={learn:{eyebrow:'SEE IT · TRY IT · UNDERSTAND IT',title:'Learn with AI',copy:'Ask a real question in plain language and watch AI turn it into a useful, understandable answer.',href:'#learn'},create:{eyebrow:'TURN AN IDEA INTO SOMETHING VISIBLE',title:'Create with AI',copy:'Start with a rough idea. See how AI can help shape an image, plan, lesson, or presentation.',href:'#create'},business:{eyebrow:'FROM GOAL TO NEXT STEP',title:'Business & Opportunity',copy:'See how AI can organize a business goal into practical actions without burying you in jargon.',href:'#business'}};function openDestination(key){const item=data[key]||data.learn;eyebrow.textContent=item.eyebrow;title.textContent=item.title;copy.textContent=item.copy;action.href=item.href;context.hidden=false;context.querySelector('.context-close').focus({preventScroll:true})}document.querySelectorAll('[data-destination]').forEach(el=>el.addEventListener('click',()=>openDestination(el.dataset.destination)));context.querySelector('.context-close').addEventListener('click',()=>{context.hidden=true;document.querySelector('.primary-path').focus({preventScroll:true})});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!context.hidden)context.querySelector('.context-close').click()});toggle.addEventListener('click',()=>{const on=body.classList.toggle('reduced-motion');toggle.setAttribute('aria-pressed',String(on));toggle.textContent=on?'Restore motion':'Reduce motion'})})();